        public const string Offset = "surface.offset";
        /// <summary>Patch (SURFACE › CREATE).</summary>
        /// <remarks>sketch?: id|name and profiles? (planar patches of sketch regions) | edges: [[x,y,z]] (points on a closed loop of a body's edges: one face on them, planar when the loop is, else a smooth B-spline surface) and body?; continuity?: g0|g1|g2 (edges only, default g0: how the patch meets the faces beside the loop — g1 their tangent planes, g2 also their curvature across the edges) or [{edge: [x,y,z], g: g0|g1|g2}] (those edges so, the rest g0) or {all, edges}; points?: [[x,y,z]] (edges only, up to 64: points the patch passes through); crown?: number −0.9…3 (default 0: only a fitted patch, whose middle becomes fuller by this many times the loop's size — the bump vanishes on the loop, so the face still meets the picked edges and the continuity across them; a loop that is planar and g0 is the exact plane whatever the crown; with points, crown needs a g1 or g2 edge); name?, body_name?</remarks>
        public const string Patch = "surface.patch";
        /// <summary>Reverse Normal (SURFACE › MODIFY).</summary>
        /// <remarks>body (a surface); faces?: [[x,y,z]] (points on the faces to turn over; default: all of them)</remarks>
        public const string ReverseNormal = "surface.reverse_normal";
        /// <summary>Surface Revolve (SURFACE › CREATE).</summary>
        /// <remarks>sketch?: id|name; curves?: [curve ids] and/or profiles? (as surface.extrude); axis: sketch line id|x|y|X|Y|Z|construction axis name|{origin, dir} | {edge|face: [x,y,z]} (a straight or circular edge, or a cylinder, cone or torus face: about its axis, followed as the model changes); angle?: expr (default 360 deg); angle2?: expr (the other side); symmetric?: bool; name?, body_name? (a surface body, no caps; a solid where a full turn closes it)</remarks>
        public const string Revolve = "surface.revolve";
        /// <summary>Ruled Surface (SURFACE › CREATE).</summary>
        /// <remarks>body; edges: [[x,y,z]] (points on a chain of its edges, open or closed); distance: expr (how far the strip reaches); mode?: normal|tangent|angle|direction (default normal: along the normal of the face beside each edge; tangent: continuing it); angle?: expr (angle mode: from `direction`, else from the face's normal, turned away from the face; 90 deg from the normal is tangent); direction?: [x,y,z] (direction mode: the rulings; angle mode: the reference, e.g. a pull direction for a draft); face?: [x,y,z] (a point on the face the directions come from; default: the face beside the most picked edges); flip?: bool (the other side); corners?: mitre|round (sharp corners of the chain; inside corners are always cut back). Lines and arcs give exact planes, cylinders and cones, other edges a fitted ruled B-spline. A new surface body</remarks>
        public const string Ruled = "surface.ruled";
        /// <summary>Stitch (SURFACE › MODIFY).</summary>
        /// <remarks>bodies: [names] (surfaces sewn into the first; a solid when they close); tolerance?: expr (default: tight)</remarks>
        public const string Stitch = "surface.stitch";
        /// <summary>Surface Sweep (SURFACE › CREATE).</summary>
        /// <remarks>sketch?: id|name; curves?: [curve ids] and/or profiles? (as surface.extrude); path_sketch: sketch; path: [curve ids in order] (a path with corners, or 3D curves, gives ruled walls mitred at the corners); orientation?, twist?, scale?, rails?, rail_fit? (as solid.sweep); name?, body_name? (a surface body, no caps)</remarks>
        public const string Sweep = "surface.sweep";
        /// <summary>Thicken (SURFACE › CREATE).</summary>
        /// <remarks>bodies: [surface names]; thickness: expr (negative: against the normal); symmetric?: bool; operation?: new|join|cut|intersect; targets?</remarks>
        public const string Thicken = "surface.thicken";
        /// <summary>Trim (SURFACE › MODIFY).</summary>
        /// <remarks>body: surface name; plane: XY|XZ|YZ|plane name|{origin, normal} or tool: {body, point} (a face, its surface extended) or curves: {sketch, curves?: [curve ids] (chains of curves meeting end to end; default every curve), direction?: normal|[x,y,z] (swept onto the surface along the sketch's normal, the default, or this direction)}; keep: [x,y,z] (a point on the side to keep) or [[x,y,z], ...] (points on the regions to keep: the pieces that hang together once cut). Mutual trim: with: another surface (one face each; leave out plane, tool and curves), keep_with: [x,y,z] or [[x,y,z], ...] (what to keep of it); each is cut where the other's surface (extended) meets it; extend?: bool (a surface that stops short of the other is extended to meet it); stitch?: bool (the kept pieces sewn into `body`; `with` is then gone)</remarks>
        public const string Trim = "surface.trim";
        /// <summary>Unstitch (SURFACE › MODIFY).</summary>
        /// <remarks>body; faces?: [[x,y,z]] (points on the faces to take out, each its own surface body; the rest stay together under the body's name; default: every face its own surface body). A solid comes apart into surfaces</remarks>
        public const string Unstitch = "surface.unstitch";
        /// <summary>Untrim (SURFACE › MODIFY).</summary>
        /// <remarks>face: {body, point}; holes?: all|[[x,y,z]] (points on the inner loops to remove; default: all); outer?: bool (restore the outer boundary to the surface's natural bounds: a free-form surface's own, an analytic surface's span of the face); in_place?: bool (untrim a surface body's face where it is; a solid's face is always copied out). A surface body; the face keeps its name</remarks>
        public const string Untrim = "surface.untrim";
    }

    /// <summary><c>timeline.*</c> commands.</summary>
    public static class Timeline
    {
        /// <summary>Add Recorded Feature (not on the toolbar).</summary>
        /// <remarks>feature: a feature as the design file and timeline.inspect hold it ({type, name?, id?, …}; the name is kept even when another feature has it, the id is kept and refused when another feature has it, so later steps can refer to them); params?: [{name, expression, unit?, comment?}] (the model parameters its sketch dimensions use); the feature goes at the marker → feature, name, error, warning</remarks>
        public const string Add = "timeline.add";
        /// <summary>Compute All (SOLID › MODIFY).</summary>
        public const string ComputeAll = "timeline.compute_all";
        /// <summary>Copy Features (not on the toolbar).</summary>
        /// <remarks>features: [ids or names] (in timeline order on paste)</remarks>
        public const string Copy = "timeline.copy";
        /// <summary>Delete (SOLID › MODIFY, shortcut Delete).</summary>
        /// <remarks>feature: id|name | features: [id|name] (one undo step; a sketch takes its dependent features with it) → deleted: [ids]; failing?: [{feature, error}] (later features that worked and now fail)</remarks>
        public const string Delete = "timeline.delete";
        /// <summary>Feature Dependents (not on the toolbar).</summary>
        /// <remarks>feature: id|name → features deleted with it, and features that would fail without it</remarks>
        public const string Dependents = "timeline.dependents";
        /// <summary>Edit Feature (not on the toolbar).</summary>
        /// <remarks>feature: id|name, set: {fields to change, merged into the feature's definition as timeline.inspect returns it, e.g. {"extent": {"distance": "30"}} (extrude), {"angle": "90 deg"} (revolve); a dotted key names a nested field ({"plane.distance": "8 mm"} = {"plane": {"distance": "8 mm"}}); expressions are text, or a number in mm or degrees} → recomputed: features rebuilt, restored: features whose earlier result for the same inputs was reused</remarks>
        public const string Edit = "timeline.edit";
        /// <summary>Export Command Script (not on the toolbar).</summary>
        /// <remarks>path?: write the script to this file → script: {commands: [...]} that rebuilds the design (solidcraft-cli eval/run), steps, omitted: what the script leaves out (appearances, folders, views, configurations); components and assemblies are not supported yet</remarks>
        public const string ExportScript = "timeline.export_script";
        /// <summary>New Feature Folder (not on the toolbar).</summary>
        /// <remarks>name?; features?: [id|name]; parent?: folder id (features leave any other timeline folder)</remarks>
        public const string Group = "timeline.group";
        /// <summary>Inspect Feature (not on the toolbar).</summary>
        /// <remarks>feature: id|name → type, definition (the fields timeline.edit's set changes, with their current values), inputs: [{label, param, expression, unit}] (named inputs parameters.change can also set), error, warning</remarks>
        public const string Inspect = "timeline.inspect";
        /// <summary>Move Timeline Items (not on the toolbar).</summary>
        /// <remarks>features?: [id|name], groups?: [folder ids], group?: folder id, position: insertion slot, active?: bool (true = the moved contents end up before the history marker, false = behind it; other features keep their state); atomically changes folder membership and moves all selected contents as one block</remarks>
        public const string MoveMany = "timeline.move_many";
        /// <summary>Move Features to Folder (not on the toolbar).</summary>
        /// <remarks>features?: [id|name], groups?: [ids], group?: id (omit or null to move to the timeline root)</remarks>
        public const string MoveToGroup = "timeline.move_to_group";
        /// <summary>Paste Features (not on the toolbar).</summary>
        /// <remarks>translate?: [x,y,z] (moves the copies' geometry); component?: where the copies go (default: the active one), component_path?: its placement (default: the active one, else its only one); the copies go at the marker, each where its original is in the world (copies into their own component keep its coordinates)</remarks>
        public const string Paste = "timeline.paste";
        /// <summary>Edit Feature (not on the toolbar).</summary>
        /// <remarks>feature: id|name, command: the feature's command id, params: its parameters (the feature is rebuilt in place)</remarks>
        public const string Redefine = "timeline.redefine";
        /// <summary>Rename (not on the toolbar).</summary>
        /// <remarks>feature: id|name, name (references to it follow)</remarks>
        public const string Rename = "timeline.rename";
        /// <summary>Rename Feature Folder (not on the toolbar).</summary>
        /// <remarks>group: id, name</remarks>
        public const string RenameGroup = "timeline.rename_group";
        /// <summary>Reorder Feature (not on the toolbar).</summary>
        /// <remarks>feature: id|name, position: its new index, active?: bool (true = it ends up before the history marker, false = behind it; other features keep their state); refused when a feature that worked would fail, unless allow_errors?: bool (default false): then made, and broken: [{feature, error}] lists the features it broke</remarks>
        public const string Reorder = "timeline.reorder";
        /// <summary>Reorder Features (not on the toolbar).</summary>
        /// <remarks>features: [id|name], position: insertion slot in the current history; selected features keep their relative order; active?: bool (as timeline.reorder's); refused when a feature that worked would fail, unless allow_errors?: bool (default false): then made, and broken: [{feature, error}] lists the features it broke</remarks>
        public const string ReorderMany = "timeline.reorder_many";
        /// <summary>Roll History Marker (not on the toolbar).</summary>
        /// <remarks>position: number of features to keep active, or "end" (omit = end) | feature: id|name (the marker goes right after it)</remarks>
        public const string RollTo = "timeline.roll_to";
        /// <summary>Move Timeline Marker (not on the toolbar).</summary>
        /// <remarks>position: number of features to keep active, or "end" (omit = end)</remarks>
        public const string Rollback = "timeline.rollback";
        /// <summary>Suppress Feature (not on the toolbar).</summary>
        /// <remarks>feature: id|name | features: [id|name] (one undo step), suppressed?: bool (default toggles: several features are all suppressed unless all of them already are, then all are unsuppressed) → feature: id (or features: [ids]), suppressed</remarks>
        public const string Suppress = "timeline.suppress";
        /// <summary>Remove Feature Folders (not on the toolbar).</summary>
        /// <remarks>group: id | groups: [ids] (features remain in the timeline)</remarks>
        public const string Ungroup = "timeline.ungroup";
    }

